            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, &nested).unwrap();
        assert!(path.exists());
        assert!(nested.is_dir());
    }

    #[test]
    fn save_report_none_exit_code_round_trip() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "signal",
            "long-running",
            None,
            "killed",
            "retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.exit_code, None);
    }

    #[test]
    fn reports_dir_ends_with_expected_segments() {
        let dir = reports_dir();
        let components: Vec<_> = dir.components().collect();
        let last_two: Vec<_> = components
            .iter()
            .rev()
            .take(2)
            .collect();

        assert_eq!(
            dir.file_name().unwrap().to_str().unwrap(),
            "failure-reports"
        );
        assert!(dir
            .parent()
            .unwrap()
            .file_name()
            .unwrap()
            .to_str()
            .unwrap()
            == ".bivvy");
    }

    #[test]
    fn failure_report_serde_all_fields() {
        let report = FailureReport {
            step_name: "npm".to_string(),
            command_scrubbed: "npm install".to_string(),
            exit_code: Some(2),
            error_scrubbed: "ENOENT".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(loaded.step_name, report.step_name);
        assert_eq!(loaded.command_scrubbed, report.command_scrubbed);
        assert_eq!(loaded.exit_code, report.exit_code);
        assert_eq!(loaded.error_scrubbed, report.error_scrubbed);
        assert_eq!(loaded.recovery_action, report.recovery_action);
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }

    #[test]
    fn consent_variants_are_distinct() {
        let variants = [
            TelemetryConsent::Send,
            TelemetryConsent::NoThanks,
            TelemetryConsent::Always,
            TelemetryConsent::Never,
        ];

        // Each pair is different
        for (i, a) in variants.iter().enumerate() {
            for (j, b) in variants.iter().enumerate() {
                if i == j {
                    assert_eq!(a, b);
                } else {
                    assert_ne!(a, b);
                }
            }
        }
    }

    #[test]
    fn build_report_includes_version_and_platform() {
        let report = build_report(
            "test",
            "echo hi",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );

        assert_eq!(report.bivvy_version, env!("CARGO_PKG_VERSION"));
        let expected_platform = format!(
            "{}-{}",
            std::env::consts::OS,
            std::env::consts::ARCH
        );
        assert_eq!(report.platform, expected_platform);
    }

    #[test]
    fn save_multiple_reports_creates_separate_files() {
        let temp = tempfile::TempDir::new().unwrap();

        let r1 = build_report("step1", "cmd1", Some(1), "e1", "retry", &HashMap::new());
        let r2 = build_report("step2", "cmd2", Some(2), "e2", "fix", &HashMap::new());

        let p1 = save_report_to(&r1, temp.path()).unwrap();
        // Small delay to ensure different timestamps
        std::thread::sleep(std::time::Duration::from_millis(1100));
        let p2 = save_report_to(&r2, temp.path()).unwrap();

        assert_ne!(p1, p2);
        assert!(p1.exists());
        assert!(p2.exists());

        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(files.len(), 2);
    }
}

